import{_ as e,c as l,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"雷泽归妹","description":"周易折中 - 雷泽归妹","frontmatter":{"title":"雷泽归妹","description":"周易折中 - 雷泽归妹"},"headers":[],"relativePath":"zh/classics/zhezhong/060.md","filePath":"zh/classics/zhezhong/060.md"}'),h={name:"zh/classics/zhezhong/060.md"};function n(d,a,p,t,s,o){return r(),l("div",null,[...a[0]||(a[0]=[i('<h1 id="雷泽归妹" tabindex="-1">雷泽归妹 <a class="header-anchor" href="#雷泽归妹" aria-label="Permalink to “雷泽归妹”">​</a></h1><h3 id="程传" tabindex="-1">程传 <a class="header-anchor" href="#程传" aria-label="Permalink to “程传”">​</a></h3><p>〈归妹序卦〉：“渐者进也，进必有所归，故受之以归妹。进则必有所至，故渐有归义，归妹所以继渐也。归妹者，女之归也。妹，少女之称。为卦震上兑下，以少女从长男也。男动而女说，又以说而动，皆男说女、女从男之义。卦有男女配合之义者四：咸、恒、渐、归妹也。咸，男女之相感也。男下女，二气感应止而说，男女之情相感之象。恒，常也。男上女下，巽顺而动，阴阳皆相应，是男女居室夫妇唱随之常道。渐，女归之得其正也。男下女而各得正位，止静而巽顺，其进有渐，男女配合得其道也。归妹，女之嫁归也。男上女下，女从男也，而有说少之义。以说而动，动以说则不得其正矣，故位皆不当。初与上虽当阴阳之位，而阳在下阴在上，亦不当位也。与渐正相对。咸、恒夫妇之道，渐、归妹女归之义。咸与归妹，男女之情也。咸止而说，归妹动于说，皆以说也。恒与渐，夫妇之义也。恒巽而动，渐止而巽，皆以巽顺也。男女之道，夫妇之义，备于是矣。归妹为卦，泽上有雷，雷震而泽动，从之象也。物之随动莫如水，男动于上而女从之，嫁归从男之象。震长男，兑少女，少女从长男以说而动，动而相说也。人之所说者少女，故云妹为女归之象，又有长男说少女之义，故为归妹也。”</p><p>归妹：征凶，无攸利</p><h3 id="本义" tabindex="-1">本义 <a class="header-anchor" href="#本义" aria-label="Permalink to “本义”">​</a></h3><p>妇人谓嫁曰归妹。少女也，兑以少女而从震之长男，而其情又为以说而动，皆非正也。故卦为归妹，而卦之诸爻自二至五皆不得正，三五又皆以柔乘刚。故其占，征凶而无所利也。</p><h3 id="程传-1" tabindex="-1">程传 <a class="header-anchor" href="#程传-1" aria-label="Permalink to “程传”">​</a></h3><p>以说而动，动而不当，故凶。不当位，不当也。征凶，动则凶也。如卦之义，不独女归无所往而利也。</p><h3 id="集说" tabindex="-1">集说 <a class="header-anchor" href="#集说" aria-label="Permalink to “集说”">​</a></h3><ul><li>蔡氏清曰 ：不曰“妹归”而曰“归妹”，“归”者在妹也。如渐则曰“女归”矣。</li></ul><p>蔡氏清曰 ：不曰“妹归”而曰“归妹”，“归”者在妹也。如渐则曰“女归”矣。</p><ul><li>张氏振渊曰 ：妹乃少女而从长男，又其情以说而动，是其情胜而不计乎匹偶之宜者，故为归妹。所归在妹，不正可知，故凶而无所利也。案归妹文意如《春秋》归地、归田之例，以物归于人，非其人来取物也。归妹所以失者有二：一则不待取而自归，失昏姻之礼（与咸之男下女相反也）；一则以少女归长男，失昏姻之时（与咸两少之交相反也）。故不曰“妹归”而曰“归妹”，以明其失礼；不曰“归女”而曰“归妹”，以见其失时。凡彖辞直著吉凶而无他戒者，大有、鼎直曰“元亨”，此直曰“征凶无攸利”。盖尊贤育才者人君之盛节也，自媒自荐者士女之丑行也。</li></ul><p>张氏振渊曰 ：妹乃少女而从长男，又其情以说而动，是其情胜而不计乎匹偶之宜者，故为归妹。所归在妹，不正可知，故凶而无所利也。案归妹文意如《春秋》归地、归田之例，以物归于人，非其人来取物也。归妹所以失者有二：一则不待取而自归，失昏姻之礼（与咸之男下女相反也）；一则以少女归长男，失昏姻之时（与咸两少之交相反也）。故不曰“妹归”而曰“归妹”，以明其失礼；不曰“归女”而曰“归妹”，以见其失时。凡彖辞直著吉凶而无他戒者，大有、鼎直曰“元亨”，此直曰“征凶无攸利”。盖尊贤育才者人君之盛节也，自媒自荐者士女之丑行也。</p><p>象曰：泽上有雷，归妹。君子以永终知敝</p><h3 id="本义-1" tabindex="-1">本义 <a class="header-anchor" href="#本义-1" aria-label="Permalink to “本义”">​</a></h3><p>雷动泽随，归妹之象。君子观其合之不正，知其终之有敝也。推之事物，莫不皆然。</p><h3 id="程传-2" tabindex="-1">程传 <a class="header-anchor" href="#程传-2" aria-label="Permalink to “程传”">​</a></h3><p>雷震于上，泽随而动，阳动于上，阴说而从，女从男之象也，故为归妹。君子观男女配合生息相续之象，而以永其终，知有敝也。永终谓生息嗣续，永久其传也；知敝谓知物有敝坏而为相继之道也。女归则有生息，故有永终之义。又夫妇之道当常永有终，必知其有敝坏之理而戒愼之。敝坏谓离隙。归妹说以动者也，异乎恒之巽而动，渐之止而巽也。少女之说情之感动，动则失正，非夫妇正而可常之道，久必敝坏。知其必敝，则当思永其终也。天下之反目者，皆不能永终者也。不独夫妇之道，天下之事莫不有终有敝，莫不有可继可久之道。观归妹，则当思永终之戒也。</p><h3 id="集说-1" tabindex="-1">集说 <a class="header-anchor" href="#集说-1" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>崔氏憬曰 ：归妹，人之始终也。始则征凶，终则无攸利，故君子以永终知敝为戒者也。</p></li><li><p>吴氏曰 ：慎曰永终知敝，言远虑其终而知有敝也。《氓》之诗不思其反，所以终见弃于人与。</p></li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>泽上有雷，不当以泽从雷取象，当以泽感雷取象。盖取于阴气先动，为归妹之义。</p><p>归妹，天地之大义也；天地不交而万物不兴，妇妹人之终始也</p><h3 id="本义-2" tabindex="-1">本义 <a class="header-anchor" href="#本义-2" aria-label="Permalink to “本义”">​</a></h3><p>释卦名义也。归者，女之终；生育者，人之始。</p><h3 id="程传-3" tabindex="-1">程传 <a class="header-anchor" href="#程传-3" aria-label="Permalink to “程传”">​</a></h3><p>一阴一阳之谓道，阴阳交合，男女配合，天地之常理也。归妹，女归于男也，故云“天地之大义也”。男在女上，阴从阳动，故为女归之象。天地不交，则万物何从而生？女之归男，乃生生相续之道。男女交而后有生息，有生息而后其终不穷。前者有终，而后者有始，相续不穷，是人之终始也。</p><h3 id="集说-2" tabindex="-1">集说 <a class="header-anchor" href="#集说-2" aria-label="Permalink to “集说”">​</a></h3><ul><li>项氏安世曰 ：有男女然后有夫妇，天地之大义也；有夫妇然后有父子，人之终始也。</li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>将言归妹之凶，而先言其本——天地之大义。犹姤言柔遇刚之失，而又推本于天地相遇之正也。由此言之，阴阳原不可以相无，而惟当慎之始以防其敝者，是易之道也。</p><p>说以动，所归妹也</p><h3 id="本义-3" tabindex="-1">本义 <a class="header-anchor" href="#本义-3" aria-label="Permalink to “本义”">​</a></h3><p>又以卦德言之。</p><h3 id="集说-3" tabindex="-1">集说 <a class="header-anchor" href="#集说-3" aria-label="Permalink to “集说”">​</a></h3><ul><li>郑氏汝谐曰 ：长男居上，少女居下，以女下男也。少女说以动，而又先下于男，其所归者妹，故以征则凶，且无攸利。</li></ul><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><p>卦德“说以动”，则与咸之“止而说”者异矣。卦象女先于男，是所欲归者妹也；又以少女从长男，是所归者乃妹也。“所归妹”一句，兼此二意，可见其失于礼又愆于义也。夫说以动，则徇乎情；所归妹，则不能止乎礼义。此卦之所以凶乎？本义以卦德言之，实则兼卦德、卦象在内。</p><p>征凶，位不当也；无攸利，柔乘刚也</p><h3 id="本义-4" tabindex="-1">本义 <a class="header-anchor" href="#本义-4" aria-label="Permalink to “本义”">​</a></h3><p>又以卦体释卦辞。男女之交，本皆正理，唯若此卦则不得其正也。</p><h3 id="程传-4" tabindex="-1">程传 <a class="header-anchor" href="#程传-4" aria-label="Permalink to “程传”">​</a></h3><p>以二体释归妹之义。男女相感，说而动者，少女之事故。以说而动，所归者妹也。所以征则凶者，以诸爻皆不当位也。所处皆不正，何动而不凶？大率以说而动，安有不失正者？不唯位不当也，又有乘刚之过。三五皆乘刚，男女有尊卑之序，夫妇有唱随之礼，此常理也，如恒是也。苟不由常正之道，徇情肆欲，唯说是动，则夫妇渎乱。男牵欲而失其刚，妇狃说而忘其顺，如归妹之乘刚是也。所以凶，无所往而利也。夫阴阳之配合，男女之交媾，理之常也；然从欲而流放，不由义理，则淫邪无所不至，伤身败德，岂人理哉？归妹之所以凶也。</p><h3 id="集说-4" tabindex="-1">集说 <a class="header-anchor" href="#集说-4" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>陆氏希声曰 ：易以咸、恒为夫妇之道，渐、归妹为夫妇之义。渐四爻得正，故女归吉；归妹四爻失正，故征凶。</p></li><li><p>吴氏曰 ：慎曰，卦以少女从长男，则非其配偶；说以动，则恣情縦欲；中爻不正，则阴阳皆失其常；三五柔乘刚，则不顺。宜其凶也。然四者又以“说以动”为重。</p></li></ul><h3 id="案-3" tabindex="-1">案 <a class="header-anchor" href="#案-3" aria-label="Permalink to “案”">​</a></h3><p>中四爻皆失正位者，除未济外，惟睽、解及此卦。而家人、睽、渐、归妹皆言男女之道者也。家人以得位而正，故睽以失位而乖；渐以得位而吉，故归妹以失位而凶也。他卦有柔乘刚而义与归妹不同者，义与卦变相关。</p><p>初九：归妹以娣，跛能履，征吉</p><h3 id="本义-5" tabindex="-1">本义 <a class="header-anchor" href="#本义-5" aria-label="Permalink to “本义”">​</a></h3><p>初九居下而无正应，故为娣象。然阳刚在女子为贤正之德，但为娣之贱，仅能承助其君而已，故又为跛能履之象。而其占，则征吉也。</p><h3 id="程传-5" tabindex="-1">程传 <a class="header-anchor" href="#程传-5" aria-label="Permalink to “程传”">​</a></h3><p>女之归，居下而无正应，娣之象也。刚阳在妇人，为贤贞之德，而处卑顺，娣之贤正者也。处说居下，为顺义。娣之卑下，虽贤何所能为？不过自善其身以承助其君而已。如跛之能履，言不能及远也。然在其分为善，故以是而行则吉也。</p><h3 id="集说-5" tabindex="-1">集说 <a class="header-anchor" href="#集说-5" aria-label="Permalink to “集说”">​</a></h3><ul><li>孔氏颖达曰 ：征吉者，少长非偶为妻而行则凶，为娣而行则吉。</li></ul><p>孔氏颖达曰 ：征吉者，少长非偶为妻而行则凶，为娣而行则吉。</p><ul><li>胡氏瑗曰 ：跛者，足之偏也。侄娣非正配而能尽其道以配君子，犹足之虽偏而能履地而行，不至于废也。</li></ul><p>胡氏瑗曰 ：跛者，足之偏也。侄娣非正配而能尽其道以配君子，犹足之虽偏而能履地而行，不至于废也。</p><h3 id="案-4" tabindex="-1">案 <a class="header-anchor" href="#案-4" aria-label="Permalink to “案”">​</a></h3><p>初在下，娣之象。凡女之归，不待六礼备者为失礼，惟娣可以从归而不嫌于失礼；少长非偶者为失时，惟娣可以待年而不嫌于失时。是卦义虽凶，而于初则无嫌，故变“征凶”而为“征吉”也。</p><p>象曰：归妹以娣，以恒也。跛能履，吉，相承也</p><h3 id="本义-6" tabindex="-1">本义 <a class="header-anchor" href="#本义-6" aria-label="Permalink to “本义”">​</a></h3><p>恒谓有常久之德。</p><h3 id="程传-6" tabindex="-1">程传 <a class="header-anchor" href="#程传-6" aria-label="Permalink to “程传”">​</a></h3><p>归妹之义，以说而动，非夫妇能常之道。九乃刚阳有贤贞之德，虽娣之微，乃能以常者也。虽在下不能有所为，如跛者之能履，然征而吉者，以其能相承助也。能助其君，娣之吉也。</p><h3 id="集说-6" tabindex="-1">集说 <a class="header-anchor" href="#集说-6" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>郑氏汝谐曰 ：初少女且微而在下，以娣媵而归，乃其常也。娣媵不能成内助之功，虽有其德，如跛者之履耳。跛者之履，虽不足以有行，然亦可以行者，以其佐小君能相承助也。如是而征，则为安分，故吉。</p></li><li><p>俞氏琰曰 ：相承者，佐其嫡以相与奉承其夫也。</p></li></ul><h3 id="案-5" tabindex="-1">案 <a class="header-anchor" href="#案-5" aria-label="Permalink to “案”">​</a></h3><p>言以恒者，女而自归非常，惟娣则从嫡而归，乃其常也。</p><p>九二：眇能视，利幽人之贞</p><h3 id="本义-7" tabindex="-1">本义 <a class="header-anchor" href="#本义-7" aria-label="Permalink to “本义”">​</a></h3><p>眇能视，承上爻而言。九二阳刚得中，女之贤也。上有正应而反阴柔不正，乃女贤而配不良，不能大成内助之功，故为眇能视之象。而其占，则利幽人之贞也。幽人，亦抱道守正而不偶者也。</p><h3 id="程传-7" tabindex="-1">程传 <a class="header-anchor" href="#程传-7" aria-label="Permalink to “程传”">​</a></h3><p>九二阳刚而得中，女之贤正者也。上有正应而反阴柔之质，动于说者也。乃女贤而配不良，故二虽贤不能自遂以成其内助之功，适可以善其身而小施之，如眇者之能视而已，言不能及远也。男女之际，当以正礼。五虽不正，二自守其幽静贞正，乃所利也。二有刚正之德，幽静之人也。二之才如是，而言利贞者，利言宜于如是之贞，非不足而为之戒也。</p><h3 id="集说-7" tabindex="-1">集说 <a class="header-anchor" href="#集说-7" aria-label="Permalink to “集说”">​</a></h3><ul><li>郭氏雍曰 ：九二刚中，贤女也。守其幽独之操，不夺其志，故曰“利幽人之贞”。</li></ul><p>郭氏雍曰 ：九二刚中，贤女也。守其幽独之操，不夺其志，故曰“利幽人之贞”。</p><ul><li>胡氏一桂曰 ：初二“跛”、“眇”，兑毁折象。履卦六三亦兑体，故取象同。</li></ul><p>胡氏一桂曰 ：初二“跛”、“眇”，兑毁折象。履卦六三亦兑体，故取象同。</p><h3 id="案-6" tabindex="-1">案 <a class="header-anchor" href="#案-6" aria-label="Permalink to “案”">​</a></h3><p>此卦与渐相似。凡以阴应阳者，女之有配者也；以阴应阴、以阳应阳者，女之无配者也。若以阳应阴，则虽有应而反莫类比之，无应者加甚矣，乃女之有配而失配者也。卫诗曰：“汎彼柏舟，亦汎其流”，则配之不良者也；又曰：“汎彼柏舟，在彼中河”，则配之不终者也。然皆自执其志，如石之不移，至于之死而矢靡他，岂非所谓“幽人之贞”乎？凡足以两而行，目以两而明，夫妇以两而成。跛者一正而一偏也，眇者一昏而一明也。娣虽屈于偏侧而犹能佐理，故曰“能履”；幽人虽失所仰望，而其志炯然，故曰“能视”。</p><p>象曰：利幽人之贞，未变常也</p><h3 id="程传-8" tabindex="-1">程传 <a class="header-anchor" href="#程传-8" aria-label="Permalink to “程传”">​</a></h3><p>守其幽贞，未失夫妇常正之道也。世人以媟狎为常，故以贞静为变常，不知乃常久之道也。</p><h3 id="集说-8" tabindex="-1">集说 <a class="header-anchor" href="#集说-8" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>俞氏琰曰 ：屯六二曰“反常”，谓字乃女子之常，不字则非常。至十年之后而乃字，则返其常也。此曰“未变常”，谓嫁者女子之常，九二不愿嫁，似乎变常，然能以幽静自守，是亦女德之常，未为变常也。</p></li><li><p>来氏知德曰 ：一与之齐，终身不改，此妇道之常也。守幽人之贞，则未变其常矣。</p></li></ul><p>六三：归妹以须，反归以娣</p><h3 id="本义-8" tabindex="-1">本义 <a class="header-anchor" href="#本义-8" aria-label="Permalink to “本义”">​</a></h3><p>六三阴柔而不中正，又为说之主，女之不正，人莫之取者也。故为未得所适而反归为娣之象，或曰“须”，女之贱者。</p><h3 id="程传-9" tabindex="-1">程传 <a class="header-anchor" href="#程传-9" aria-label="Permalink to “程传”">​</a></h3><p>三居下之上，本非贱者，以失德而无正应，故为欲有归而未得其归，须待也。待者，未有所适也。六居三不当位，德不正也，柔而尚刚，行不顺也。为说之主，以说求归，动非礼也。上无应，无受之者也，无所适，故须也。女子之处如是，人谁取之？不可以为人配矣。当反归而求为娣媵则可也，以不正而失其所也。</p><h3 id="集说-9" tabindex="-1">集说 <a class="header-anchor" href="#集说-9" aria-label="Permalink to “集说”">​</a></h3><ul><li>陆氏希声曰 ：在天文，织女为贵，须女为贱。</li></ul><p>陆氏希声曰 ：在天文，织女为贵，须女为贱。</p><ul><li>胡氏炳文曰 ：初九居下，娣也。六三居下之上，非娣也。阴柔而不中正，又为兑说之主，无德之女也。无德之女，人无取之者，故本宜须而反归以娣也。</li></ul><p>胡氏炳文曰 ：初九居下，娣也。六三居下之上，非娣也。阴柔而不中正，又为兑说之主，无德之女也。无德之女，人无取之者，故本宜须而反归以娣也。</p><h3 id="案-7" tabindex="-1">案 <a class="header-anchor" href="#案-7" aria-label="Permalink to “案”">​</a></h3><p>须当从本义贱女之解。是为三不中正而无应，故取象于女之贱者，人不之取，但反归而为娣也。然亦惟下卦无应，有娣之象；从在上之同类而归也。上卦无应，则并无娣之象矣。故在四为愆期，在上为虚筐。</p><p>象曰：归妹以须，未当也</p><h3 id="程传-10" tabindex="-1">程传 <a class="header-anchor" href="#程传-10" aria-label="Permalink to “程传”">​</a></h3><p>未当者，其处其德其求归之道皆不当，故无取之者，所以须也。</p><h3 id="集说-10" tabindex="-1">集说 <a class="header-anchor" href="#集说-10" aria-label="Permalink to “集说”">​</a></h3><ul><li>朱氏震曰 ：六三居不当位，德不正也。柔而上刚，行不顺也。为说之主，以说而归，动非礼也。上无应，无受之者也。如是而贱矣，故曰“未当也”。未当故无取之者，反归以娣也。</li></ul><p>九四：归妹，愆期，迟归有时。</p><h3 id="本义-9" tabindex="-1">本义 <a class="header-anchor" href="#本义-9" aria-label="Permalink to “本义”">​</a></h3><p>九四以阳居上体而无正应，贤女不轻从人而愆期，以待所归之象，正与六三相反。</p><h3 id="程传-11" tabindex="-1">程传 <a class="header-anchor" href="#程传-11" aria-label="Permalink to “程传”">​</a></h3><p>九以阳居四，四上体地之高也。阳刚在女子为正徳，贤明者也。无正应，未得其归也。过时未归，故云愆期。女子居贵高之地，有贤明之资，人情所愿取，故其愆期乃为有时，盖自有待，非不售也。待得佳配而后行也。九居四虽不当位而处柔，乃妇人之道。以无应，故为愆期之义。而圣人推理以女贤而愆期，盖有待也。</p><h3 id="集说-11" tabindex="-1">集说 <a class="header-anchor" href="#集说-11" aria-label="Permalink to “集说”">​</a></h3><ul><li>胡氏瑗曰：以刚阳之质居阴柔之位，不为躁进，故待其礼之全备，俟其年之长大，然后归于君子，斯得其时也。迟待也。</li></ul><p>象曰：愆期之志，有待而行也</p><h3 id="程传-12" tabindex="-1">程传 <a class="header-anchor" href="#程传-12" aria-label="Permalink to “程传”">​</a></h3><p>所以愆期者，由已而不由彼。贤女人所愿取，所以愆期，乃其志欲有所待，待得佳配而后行也。</p><h3 id="集说-12" tabindex="-1">集说 <a class="header-anchor" href="#集说-12" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颖达曰 ：嫁宜及时，今乃过期而迟归者，此嫁者之志欲有所待而后乃行也。</p></li><li><p>俞氏琰曰 ：爻辞言愆期，而爻传直述其志，以见愆期在我而不苟从人，盖有待而行，非为人所弃也。行谓出嫁，《诗·泉水》云：“女子有行”是也。</p></li></ul><p>六五：帝乙归妹，其君之袂不如其娣之袂，良月几望，吉。</p><h3 id="本义-10" tabindex="-1">本义 <a class="header-anchor" href="#本义-10" aria-label="Permalink to “本义”">​</a></h3><p>六五柔中居尊，下应九二，尚徳而不贵饰，故为帝女下嫁而服不盛之象。然女徳之盛无以加此，故又为月几望之象，而占者如之则吉也。</p><h3 id="程传-13" tabindex="-1">程传 <a class="header-anchor" href="#程传-13" aria-label="Permalink to “程传”">​</a></h3><p>六五居尊位，妹之贵高者也。下应于二，为下嫁之象。王姬下嫁，自古而然。至帝乙而后正昏姻之礼，明男女之分。虽至贵之女，不得失柔巽之道，有贵骄之志。故《易》中阴尊而谦降者，则曰帝乙归妹（《泰》六五是也）。贵女之归，唯谦降以从礼，乃尊高之徳也。不事容饰以说于人，娣媵者以容饰为事者也。衣袂所以为容饰也。六五尊贵之女，尚礼而不尚饰，故其袂不及其娣之袂良也。良，羙好也。月望，阴之盈也，盈则敌阳矣。几望，未至于盈也。五之贵高，常不至于盈极，则不亢其夫，乃为吉也。女之处尊贵之道也。</p><h3 id="集说-13" tabindex="-1">集说 <a class="header-anchor" href="#集说-13" aria-label="Permalink to “集说”">​</a></h3><ul><li>薛氏温其曰：至尊之妹必归于夫人伦之正。案，女不待夫家之求而自归，非正也，卦之所以凶也。然惟天子之女，则必求于夫家而自归焉，是归妹之义。在他人则为越礼犯义而凶，在天子则为降尊屈贵而吉矣。六五居尊而下应九二，适合此象，故其辞如此。卦惟此爻有应，而又于归妹之义正为所宜，而非所病，则其为吉宜矣。</li></ul><p>站长：晚清尚秉和著有《周易尚氏学》，其中论点认为，西汉时期的易学家孟喜、荀爽皆做「月既望」，详情可看本站的《周易尚氏学》。</p><p>象曰：帝乙归妹，不如其娣之袂良也；其位在中，以贵行也</p><h3 id="本义-11" tabindex="-1">本义 <a class="header-anchor" href="#本义-11" aria-label="Permalink to “本义”">​</a></h3><p>以其有中德之贵而行，故不尚饬。</p><h3 id="程传-14" tabindex="-1">程传 <a class="header-anchor" href="#程传-14" aria-label="Permalink to “程传”">​</a></h3><p>以帝乙归妹之道言，其袂不如其娣之袂良，尚礼而不尚饰也。五以柔中在尊高之位，以尊贵而行中道也。柔顺降屈，尚礼而不尚饰，乃中道也。</p><h3 id="集说-14" tabindex="-1">集说 <a class="header-anchor" href="#集说-14" aria-label="Permalink to “集说”">​</a></h3><ul><li>王氏申子曰 ：上二句举爻辞，下二句释之也。言五居尊位而用中，故能以至贵而行其勤俭谦逊之道也。</li></ul><p>上六：女承筐无实，士刲羊无血，无攸利。</p><h3 id="本义-12" tabindex="-1">本义 <a class="header-anchor" href="#本义-12" aria-label="Permalink to “本义”">​</a></h3><p>上六以阴柔居归妹之终而无应，约婚而不终者也，故其象如此，而于占为无所利也。</p><h3 id="程传-15" tabindex="-1">程传 <a class="header-anchor" href="#程传-15" aria-label="Permalink to “程传”">​</a></h3><p>上六女归之终而无应，女归之无终者也。妇者所以承先祖奉祭祀，不能奉祭祀，则不可以为妇矣。筐篚之实，妇职所供也。古者房中之爼、葅歜之类，后夫人职之。诸侯之祭，亲割牲，卿士大夫皆然。割取血以祭，礼云血祭盛气也。女当承事筐篚而无实，无实则无以祭，谓不能奉祭祀也。夫妇共承宗庙，妇不能奉祭祀，乃夫不能承祭祀也。故刲羊而无血，亦无以祭也，谓不可以承祭祀也。妇不能奉祭祀，则当离绝矣，是夫妇之无终者也。何所往而利哉？</p><h3 id="集说-15" tabindex="-1">集说 <a class="header-anchor" href="#集说-15" aria-label="Permalink to “集说”">​</a></h3><ul><li>胡氏炳文曰：震有虚筐之象，兑羊象。上与三皆阴虚而无应，故有承筐无实、刲羊无血之象。程传以为女归之无终，本义以为约婚而不终。盖曰士曰女，未成夫妇也。先女而后士，罪在女也，故无攸利之占与卦辞同。</li></ul><p>象曰：上六无实，承虚筐也</p><h3 id="程传-16" tabindex="-1">程传 <a class="header-anchor" href="#程传-16" aria-label="Permalink to “程传”">​</a></h3><p>筐无实是空筐也，空筐可以祭乎？言不可以奉祭祀也。女不可以承祭祀，则离绝而已，是女归之无终者也。</p><h3 id="集说-16" tabindex="-1">集说 <a class="header-anchor" href="#集说-16" aria-label="Permalink to “集说”">​</a></h3><ul><li>王氏宗传曰 ：专取虚筐无实为言者，上六女子也。</li></ul>',141)])])}const m=e(h,[["render",n]]);export{b as __pageData,m as default};
